(function(window) {
  'use strict';
  let hasServerApi = null; // null: test edilmedi, true: PHP API aktif, false: yerel mod
  const TOKEN_STORAGE_KEY = 'canyapi_cms_token';
  function apiUrl(endpoint) {
    const base = window.location.origin || '';
    return base + '/' + endpoint.replace(/^\/+/, '');
  }
  async function detectServerApi() {
    if (hasServerApi !== null) return hasServerApi;
    try {
      const res = await fetch(apiUrl(`api/settings.php?_t=${Date.now()}`), { method: 'GET', cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success) {
          hasServerApi = true;
          return true;
        }
      }
    } catch (e) {
    }
    hasServerApi = false;
    return false;
  }
  function getAuthToken() {
    return sessionStorage.getItem(TOKEN_STORAGE_KEY) || '05458320190';
  }
  function getAuthHeader() {
    const token = getAuthToken();
    return {
      'Content-Type': 'application/json',
      'X-Admin-Token': token,
      'Authorization': 'Bearer ' + token
    };
  }
  async function getSettings() {
    try {
      const res = await fetch(apiUrl(`api/settings.php?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const json = await res.json();
        if (json && json.success && json.data) {
          localStorage.setItem('canyapi_cms_settings', JSON.stringify(json.data));
          hasServerApi = true;
          return json.data;
        }
      }
    } catch (e) {}
    try {
      const res = await fetch(apiUrl(`data/settings.json?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        localStorage.setItem('canyapi_cms_settings', JSON.stringify(data));
        return data;
      }
    } catch (e) {}
    const local = localStorage.getItem('canyapi_cms_settings');
    if (local) {
      try { return JSON.parse(local); } catch (e) {}
    }
    return {};
  }
  async function saveSettings(settings) {
    localStorage.setItem('canyapi_cms_settings', JSON.stringify(settings));
    try {
      const payload = Object.assign({}, settings, { _token: getAuthToken() });
      const res = await fetch(apiUrl('api/settings.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        const json = await res.json();
        return json;
      }
    } catch (e) {
      console.warn('saveSettings API error:', e);
    }
    return { success: true, message: 'Ayarlar kaydedildi.', data: settings };
  }
  async function getProjects() {
    try {
      const res = await fetch(apiUrl(`api/projects.php?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const json = await res.json();
        if (json && json.success && Array.isArray(json.data)) {
          localStorage.setItem('canyapi_cms_projects', JSON.stringify(json.data));
          hasServerApi = true;
          return json.data;
        }
      }
    } catch (e) {}
    try {
      const res = await fetch(apiUrl(`data/projects.json?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data)) {
          localStorage.setItem('canyapi_cms_projects', JSON.stringify(data));
          return data;
        }
      }
    } catch (e) {}
    const local = localStorage.getItem('canyapi_cms_projects');
    if (local) {
      try { return JSON.parse(local); } catch (e) {}
    }
    return [];
  }
  async function saveProject(project) {
    try {
      const payload = Object.assign({}, project, { _token: getAuthToken() });
      const res = await fetch(apiUrl('api/projects.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_projects', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('saveProject error:', e);
    }
    let projects = await getProjects();
    if (!project.id) {
      project.id = 'proj-' + Date.now();
      projects.unshift(project);
    } else {
      const idx = projects.findIndex(p => p.id === project.id);
      if (idx !== -1) projects[idx] = Object.assign({}, projects[idx], project);
      else projects.unshift(project);
    }
    localStorage.setItem('canyapi_cms_projects', JSON.stringify(projects));
    return { success: true, message: 'Proje kaydedildi.', data: projects };
  }
  async function deleteProject(id) {
    try {
      const res = await fetch(apiUrl('api/projects.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'delete', id: id, _token: getAuthToken() })
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_projects', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('deleteProject error:', e);
    }
    let projects = await getProjects();
    projects = projects.filter(p => p.id !== id);
    localStorage.setItem('canyapi_cms_projects', JSON.stringify(projects));
    return { success: true, message: 'Proje silindi.', data: projects };
  }
  async function getServices() {
    try {
      const res = await fetch(apiUrl(`api/services.php?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const json = await res.json();
        if (json && json.success && Array.isArray(json.data)) {
          localStorage.setItem('canyapi_cms_services', JSON.stringify(json.data));
          hasServerApi = true;
          return json.data;
        }
      }
    } catch (e) {}
    try {
      const res = await fetch(apiUrl(`data/services.json?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data)) {
          localStorage.setItem('canyapi_cms_services', JSON.stringify(data));
          return data;
        }
      }
    } catch (e) {}
    const local = localStorage.getItem('canyapi_cms_services');
    if (local) {
      try { return JSON.parse(local); } catch (e) {}
    }
    return [];
  }
  async function saveService(service) {
    try {
      const payload = Object.assign({}, service, { _token: getAuthToken() });
      const res = await fetch(apiUrl('api/services.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_services', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('saveService error:', e);
    }
    let services = await getServices();
    if (!service.id) {
      service.id = 'srv-' + Date.now();
      services.push(service);
    } else {
      const idx = services.findIndex(s => s.id === service.id);
      if (idx !== -1) services[idx] = Object.assign({}, services[idx], service);
      else services.push(service);
    }
    localStorage.setItem('canyapi_cms_services', JSON.stringify(services));
    return { success: true, message: 'Hizmet kaydedildi.', data: services };
  }
  async function deleteService(id) {
    try {
      const res = await fetch(apiUrl('api/services.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'delete', id: id, _token: getAuthToken() })
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_services', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('deleteService error:', e);
    }
    let services = await getServices();
    services = services.filter(s => s.id !== id);
    localStorage.setItem('canyapi_cms_services', JSON.stringify(services));
    return { success: true, message: 'Hizmet silindi.', data: services };
  }
  async function getBlogPosts(slug = null) {
    try {
      const url = slug
        ? apiUrl(`api/blog.php?slug=${encodeURIComponent(slug)}&_t=${Date.now()}`)
        : apiUrl(`api/blog.php?all=1&_t=${Date.now()}`);
      const res = await fetch(url, { cache: 'no-store' });
      if (res.ok) {
        const json = await res.json();
        if (json && json.success && json.data) {
          if (!slug && Array.isArray(json.data)) {
            localStorage.setItem('canyapi_cms_blog', JSON.stringify(json.data));
          }
          hasServerApi = true;
          return json.data;
        }
      }
    } catch (e) {}
    let blog = [];
    try {
      const res = await fetch(apiUrl(`data/blog.json?_t=${Date.now()}`), { cache: 'no-store' });
      if (res.ok) {
        blog = await res.json();
        if (Array.isArray(blog)) {
          localStorage.setItem('canyapi_cms_blog', JSON.stringify(blog));
        }
      }
    } catch (e) {}
    if (!Array.isArray(blog) || blog.length === 0) {
      const local = localStorage.getItem('canyapi_cms_blog');
      if (local) {
        try { blog = JSON.parse(local); } catch (e) {}
      }
    }
    if (slug) {
      return (Array.isArray(blog) ? blog.find(b => b.slug === slug || b.id === slug) : null) || null;
    }
    return Array.isArray(blog) ? blog : [];
  }
  async function saveBlogPost(post) {
    try {
      const payload = Object.assign({}, post, { _token: getAuthToken() });
      const res = await fetch(apiUrl('api/blog.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify(payload)
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_blog', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('saveBlogPost error:', e);
    }
    let blog = await getBlogPosts();
    if (!post.id) {
      post.id = 'blog-' + Date.now();
      if (!post.slug) {
        post.slug = (post.title || 'yazi').toLowerCase()
          .replace(/[^a-z0-9]/g, '-')
          .replace(/-+/g, '-');
      }
      blog.unshift(post);
    } else {
      const idx = blog.findIndex(b => b.id === post.id);
      if (idx !== -1) blog[idx] = Object.assign({}, blog[idx], post);
      else blog.unshift(post);
    }
    localStorage.setItem('canyapi_cms_blog', JSON.stringify(blog));
    return { success: true, message: 'Blog yazısı kaydedildi.', data: blog };
  }
  async function deleteBlogPost(id) {
    try {
      const res = await fetch(apiUrl('api/blog.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'delete', id: id, _token: getAuthToken() })
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && data.data) {
          localStorage.setItem('canyapi_cms_blog', JSON.stringify(data.data));
          return data;
        }
      }
    } catch (e) {
      console.warn('deleteBlogPost error:', e);
    }
    let blog = await getBlogPosts();
    blog = blog.filter(b => b.id !== id);
    localStorage.setItem('canyapi_cms_blog', JSON.stringify(blog));
    return { success: true, message: 'Blog yazısı silindi.', data: blog };
  }
  async function uploadPhoto(file) {
    try {
      const formData = new FormData();
      formData.append('image', file);
      formData.append('_token', getAuthToken());
      const res = await fetch(apiUrl('api/upload.php'), {
        method: 'POST',
        headers: {
          'X-Admin-Token': getAuthToken(),
          'Authorization': 'Bearer ' + getAuthToken()
        },
        credentials: 'same-origin',
        body: formData
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (e) {
      console.warn('uploadPhoto error:', e);
    }
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = function(e) {
        const dataUrl = e.target.result;
        resolve({
          success: true,
          url: dataUrl,
          filename: file.name,
          message: 'Fotoğraf yüklendi (Önizleme/Yerel Mod).'
        });
      };
      reader.readAsDataURL(file);
    });
  }
  async function getMediaList() {
    try {
      const res = await fetch(apiUrl(`api/media.php?_t=${Date.now()}`), {
        headers: getAuthHeader(),
        cache: 'no-store'
      });
      if (res.ok) {
        const data = await res.json();
        if (data && data.success && Array.isArray(data.data)) {
          return data.data;
        }
      }
    } catch (e) {}
    return [];
  }
  async function deleteMedia(filename) {
    try {
      const res = await fetch(apiUrl('api/media.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'delete', filename: filename })
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (e) {
      console.warn('deleteMedia error:', e);
    }
    return { success: false, message: 'Görsel silinemedi.' };
  }
  async function submitLead(leadData) {
    try {
      const res = await fetch(apiUrl('api/leads.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(leadData)
      });
      if (res.ok) {
        const json = await res.json();
        return json;
      }
    } catch (e) {
      console.warn('submitLead API error, yerel yedeğe yazılıyor:', e);
    }
    const local = JSON.parse(localStorage.getItem('canyapi_leads') || '[]');
    const fallbackId = 'CY-L' + Math.floor(1000 + Math.random() * 9000);
    const newLead = Object.assign({
      id: fallbackId,
      date: new Date().toLocaleDateString('tr-TR') + ' ' + new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }),
      status: 'Yeni'
    }, leadData);
    local.unshift(newLead);
    localStorage.setItem('canyapi_leads', JSON.stringify(local));
    return {
      success: true,
      id: fallbackId,
      message: 'Talebiniz alındı (Yerel Kayıt). Ekibimiz en kısa sürede sizinle iletişime geçecektir.'
    };
  }
  async function getLeads() {
    try {
      const res = await fetch(apiUrl(`api/leads.php?_t=${Date.now()}`), {
        headers: getAuthHeader(),
        cache: 'no-store'
      });
      if (res.ok) {
        const json = await res.json();
        if (json && json.success && Array.isArray(json.data)) {
          localStorage.setItem('canyapi_leads', JSON.stringify(json.data));
          return json.data;
        }
      }
    } catch (e) {}
    return JSON.parse(localStorage.getItem('canyapi_leads') || '[]');
  }
  async function updateLeadStatus(id, status) {
    try {
      const res = await fetch(apiUrl('api/leads.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'status', id: id, status: status })
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (e) {
      console.warn('updateLeadStatus error:', e);
    }
    const local = JSON.parse(localStorage.getItem('canyapi_leads') || '[]');
    const target = local.find(l => l.id === id);
    if (target) {
      target.status = status;
      localStorage.setItem('canyapi_leads', JSON.stringify(local));
      return { success: true, message: 'Durum güncellendi (Yerel).' };
    }
    return { success: false, message: 'Talep bulunamadı.' };
  }
  async function deleteLead(id) {
    try {
      const res = await fetch(apiUrl('api/leads.php'), {
        method: 'POST',
        headers: getAuthHeader(),
        credentials: 'same-origin',
        body: JSON.stringify({ action: 'delete', id: id })
      });
      if (res.ok) {
        return await res.json();
      }
    } catch (e) {
      console.warn('deleteLead error:', e);
    }
    let local = JSON.parse(localStorage.getItem('canyapi_leads') || '[]');
    local = local.filter(l => l.id !== id);
    localStorage.setItem('canyapi_leads', JSON.stringify(local));
    return { success: true, message: 'Talep silindi (Yerel).' };
  }
  window.CmsClient = {
    detectServerApi,
    getSettings,
    saveSettings,
    getProjects,
    saveProject,
    deleteProject,
    getServices,
    saveService,
    deleteService,
    getBlogPosts,
    saveBlogPost,
    deleteBlogPost,
    uploadPhoto,
    getMediaList,
    deleteMedia,
    submitLead,
    getLeads,
    updateLeadStatus,
    deleteLead
  };
})(window);